H.background();
// bond order: 1, 2, or 3 (single/double/triple)
let bo = Math.round(P.bo);
if (bo < 1) bo = 1; if (bo > 3) bo = 3;
// representative C–C data: length (pm) and energy (kJ/mol)
const lenTab = { 1: 154, 2: 134, 3: 120 };
const enTab = { 1: 348, 2: 614, 3: 839 };
const len = lenTab[bo], en = enTab[bo];
const name = { 1: "C–C single", 2: "C=C double", 3: "C≡C triple" }[bo];
// scene: draw two carbon atoms separated by length; bond drawn as bo lines
const cx = H.W / 2, cy = 230;
// map length pm -> pixels (shorter = closer). 120..154 pm -> 200..130 px sep
const sep = H.map(len, 120, 154, 150, 220);
const vib = 4 * Math.sin(t * (1 + bo)) * (1 / bo); // stiffer (higher bo) vibrates less
const x1 = cx - sep / 2 - vib, x2 = cx + sep / 2 + vib;
// bond lines (bo of them, stacked)
for (let i = 0; i < bo; i++) {
  const off = (i - (bo - 1) / 2) * 12;
  H.line(x1, cy + off, x2, cy + off, { color: H.colors.accent, width: 4 });
}
H.circle(x1, cy, 34, { fill: H.colors.panel, stroke: H.colors.ink, width: 2 });
H.circle(x2, cy, 34, { fill: H.colors.panel, stroke: H.colors.ink, width: 2 });
H.text("C", x1, cy + 1, { color: H.colors.ink, size: 20, align: "center", baseline: "middle", weight: 700 });
H.text("C", x2, cy + 1, { color: H.colors.ink, size: 20, align: "center", baseline: "middle", weight: 700 });
// length annotation
H.line(x1, cy + 70, x2, cy + 70, { color: H.colors.sub, width: 1 });
H.text(len + " pm", cx, cy + 88, { color: H.colors.sub, size: 13, align: "center" });
// energy bar (animated fill / pulse)
const barX = 560, barY0 = 380, barW = 60;
const maxEn = 900;
const fullH = 260;
const h = (en / maxEn) * fullH;
const grow = 0.92 + 0.08 * (0.5 + 0.5 * Math.sin(t * 2));
H.rect(barX, barY0 - fullH, barW, fullH, { stroke: H.colors.grid, width: 1 });
H.rect(barX, barY0 - h * grow, barW, h * grow, { fill: H.colors.warn });
H.text("bond energy", barX + barW / 2, barY0 + 20, { color: H.colors.sub, size: 12, align: "center" });
H.text(en + " kJ/mol", barX + barW / 2, barY0 - h - 10, { color: H.colors.warn, size: 13, align: "center", weight: 700 });
H.text("Bond order ↑  →  shorter & stronger bond", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("More shared pairs pull nuclei closer; harder to break", 24, 52, { color: H.colors.sub, size: 13 });
H.text(name + ":  length " + len + " pm,  energy " + en + " kJ/mol", 24, 74, { color: H.colors.accent, size: 14, weight: 700 });
